# prompts.py - picture prompts for not-a-bomb (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
# NAVY role block = the officer role of titanic-cover (#36), word for word, for the HERO; after measuring the hero the block
# became NAVY2 (cap white #FBFAF9 / shade #E7E6E9, black #131211 visor + band, gold #FBCA43 cord + anchor badge) for every later picture.
import json, sys
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
NAVY = " This character is a navy officer: exactly the same simple white character, wearing only a white naval officer's peaked cap with a black visor and a small gold badge on the front (flat white #FFFFFF crown with a pale grey #E3E6EA shade, black #1A1A1A visor, gold #F2C230 badge) sitting on top of the round head - nothing else added, no hair, no clothes."
NAVY2 = " This character is a navy officer: exactly the same simple white character, wearing only a white naval officer's peaked cap with a black visor, a black band with a thin gold cord across it and a black oval badge with a small gold anchor on the front (flat white #FBFAF9 crown with a pale grey #E7E6E9 shade, black #131211 visor and band, gold #FBCA43 cord and anchor, as measured on the hero) sitting on top of the round head - nothing else added, no hair, no clothes."
FISHER = " This character is a fisherman: exactly the same simple white character, wearing only a bright yellow fisherman's rain hat (a sou'wester with a round crown and a wide floppy brim that is longer at the back, flat #F6C21C with a darker #D9A30F shade) on top of the round head - nothing else added, no hair, no clothes."
PRESS = " This character is a newspaper reporter: exactly the same simple white character, wearing only a brown fedora hat (flat #8A5A3B with a darker #5E3C25 hat band) with a small blank white card tucked into the hat band, sitting on top of the round head - nothing else added, no hair, no clothes."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no letters, no numbers, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
ROW3 = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, no ground drawn, bold clean thick outlines. "
def tail(role, key='green'): return " Whole bodies in frame with a margin. " + CHAR + role + " " + KEY(key)

P = {
 'hero': ("2:3", "Full body, three-quarter view facing to the right, standing straight and saluting: the hand on the RIGHT side of the image raised to the cap visor in a crisp salute, the other arm straight down along the body, a serious proud face with lowered eyebrows and a small closed mouth. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + NAVY + " " + KEY()),
 'officer3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the RIGHT, looking through a pair of black binoculars held up to the eyes with both hands, leaning forward a little, eyebrows raised. MIDDLE copy: facing the viewer, nervous: one hand raised beside the head holding up a short wooden stick with a completely blank plain white rectangular sign board on top (wider than the head, no writing on it), the other hand scratching the back of the head, a big forced toothy smile, eyebrows tilted up in the middle, eyes wide. RIGHT copy: three-quarter view facing to the LEFT, proudly presenting: one arm stretched out to the side at waist height with the open palm facing up as if showing off something big next to him, the other hand on the hip, chin up, a big proud open smile with the pink tongue showing." + tail(NAVY2)),
 'fisher3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the RIGHT, surprised: one arm stretched up diagonally pointing at the sky to the upper right, the head tilted back looking up, eyes wide, eyebrows raised high, a small round open mouth. MIDDLE copy: facing the viewer, shocked: both hands pressed on the cheeks, eyes wide, eyebrows raised high, mouth wide open in a scream with the pink tongue showing. RIGHT copy: three-quarter view facing to the LEFT, helpful: one arm stretched forward and down pointing at the ground in front of him, looking at the viewer, eyebrows raised, mouth open talking." + tail(FISHER)),
 'press3': ("3:2", ROW3 + "LEFT copy: three-quarter view facing to the LEFT, taking a photo: holding a big old-fashioned black press camera with a round silver flash dish on its side up in front of the face with both hands, one eye squinting behind it, a grin. MIDDLE copy: three-quarter view facing to the LEFT, eager: leaning forward and holding a round old black microphone out in front with one stretched arm, the other hand holding a small open notepad, eyebrows raised, mouth wide open asking a question. RIGHT copy: three-quarter view facing to the LEFT, writing fast with a pencil in a small notepad held at chest height, eyes on the notepad, the pink tongue poking out of the corner of the mouth in concentration." + tail(PRESS)),
 'objects': ("3:2", "Two separate objects side by side in one row with a wide empty gap between them, drawn at the same scale. LEFT: a big fat rounded metal capsule shaped like a chubby torpedo, lying horizontally with its rounded nose pointing to the LEFT and four small flat tail fins at its RIGHT end, flat pale olive-grey (#A7AE9C with a darker #7F8774 shade on the bottom side), two thin dark grey bands around the body, a small round lifting lug on top; about three times as long as it is tall. RIGHT: a small wooden fishing boat seen exactly from the side with its pointed bow to the LEFT: a white hull (#F4F2EC with a pale grey #D8D6D0 shade) with one bright blue stripe (#2E7FC1) along the top edge and a red-brown bottom part (#A6472D), a low flat deck, one short wooden mast in the middle, the bottom of the hull is a gentle curve. No people, no nets, no water, no faces, no markings, no letters, no numbers. " + OBJ + " " + KEY('magenta')),
 'sea': ("2:3", "A calm sunny Mediterranean sea seen from the side, vertical picture. The top 56 % is a clear light-blue sky (#8ED3F5 at the top to #CFEFFC near the horizon) with two small simple white puffy clouds. The horizon is a flat straight line at 56 % of the height; on the LEFT half of the horizon a low line of dry ochre-brown hills (#C9A267 with a darker #A88148 shade) with a few tiny white cube-shaped houses with flat roofs. Below the horizon a calm bright blue sea (#2189CF with a lighter #4AAEE5 band near the horizon) with a few long flat lighter wave lines, open water filling the whole bottom of the picture. No boats, no people, no birds, no sun, no text. " + BG),
 'deep': ("2:3", "Deep under the sea, vertical picture, side view. Dark blue water fills the picture (#123A63 at the top fading to #0A2340 at the bottom). A steep rocky underwater slope rises from the bottom LEFT corner up to the RIGHT edge at about 40 % of the height, a straight steep diagonal; the slope is grey-brown rock (#57524B with a darker #3E3A35 shade) covered with a thin layer of soft grey mud (#77756C) on its top surface, a few small round rocks on it. The upper LEFT part of the picture is open dark water. No plants, no fish, no light beams, no objects, no text. " + BG),
 'deck': ("2:3", "The flat back deck of a grey navy ship seen from the side at deck level, vertical picture. The bottom 30 % of the picture is the flat steel deck (#8F989F with a darker #6F787F shade) seen slightly from above, with a few straight rivet seam lines. Along the back edge of the deck, at 70 % of the height, a simple white metal railing with three horizontal bars runs across the whole width. Behind the railing a calm blue sea (#2189CF with a lighter #4AAEE5 band near the horizon) up to a flat horizon at 52 % of the height, and above it a clear light-blue sky (#8ED3F5 to #CFEFFC). No people, no objects on the deck, no crane, no flags, no text. " + BG),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# not-a-bomb - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
